import type { VideoRef } from '../components/Video'

export interface PrereqCheck {
  question: string
  options: string[]
  answer: number
  explain: string
}

export interface Prereq {
  id: string
  name: string
  group: PrereqGroup
  /** one-line analogy or picture in words; $…$ renders as math */
  hook: string
  /** three to five short lines: the math you must be able to write */
  bullets: string[]
  /** id of an interactive picture from components/prereq-widgets */
  widget?: string
  /** one line: where this bites on the midterm */
  why?: string
  /** full one-paragraph lesson, folded under “Full lesson”; $…$ renders as math */
  lesson: string
  lectures: number[]
  dependsOn?: string[]
  /** optional one-question self-check; graded attempts are tagged with the prerequisite id */
  check?: PrereqCheck
  /** id of an inline SVG concept diagram from components/figures */
  figure?: string
  /** verified YouTube references or honest search boxes (components/Video) */
  videos?: VideoRef[]
}

export type PrereqGroup = 'Filters from scratch' | 'Signals and systems' | 'Probability and Gaussian models' | 'Linear algebra and calculus' | 'Graphs and Markov random fields' | 'Optimization'

export const prereqGroups: PrereqGroup[] = ['Filters from scratch', 'Signals and systems', 'Probability and Gaussian models', 'Linear algebra and calculus', 'Graphs and Markov random fields', 'Optimization']

export const prereqs: Prereq[] = [
  // ---- Filters from scratch --------------------------------------------------
  { id: 'what-is-a-filter', name: "What a filter is: impulse response and taps", group: 'Filters from scratch', lectures: [7, 12, 13], hook: "A filter is a recipe for mixing a signal with delayed copies of itself. Poke it with a single spike and the output you see, $h_n$, is the whole recipe written out. Real world: shout once in a canyon and the pattern of echoes you hear is the canyon’s impulse response.", bullets: ["Output = weighted sum of delayed inputs: $y_n = \\sum_k h_k\\,x_{n-k}$. The weights $h_k$ are the taps.", "Input $\\delta_n$ (one spike) $\\Rightarrow$ output $h_n$: the impulse response is the filter, nothing is hidden.", "A 3-day moving average is a filter with taps $\\tfrac13,\\tfrac13,\\tfrac13$; a camera blur is a 2-D filter whose taps spread a point of light over its neighbours.", "In this course: the prediction filter $h_n$ (lecture 7), the GMRF predictor $g_n$, and the blur $a_s$ (lectures 12–13) are all filters."], why: "Every model in lectures 7–13 is ‘white noise or an image, pushed through a filter’. If you can read taps, you can read the model.", figure: 'impulse-response', videos: [{"id": "KuXjwB4LzSA", "title": "But what is a convolution?", "channel": "3Blue1Brown"}, {"id": "1RIA9U5oXro", "title": "How Digital Audio Works", "channel": "Computerphile"}], lesson: "A filter takes a sequence in and puts a sequence out by forming, at every time $n$, a weighted sum of the current and past (or, for a noncausal filter, future) inputs: $y_n = \\sum_k h_k x_{n-k}$. The list of weights $h_k$ is called the taps, and the sequence $h_n$ itself is called the impulse response because it is literally what comes out when the input is a single unit spike $\\delta_n$. That is the key practical fact: to learn everything about a linear filter, feed it one spike and record the ring-out. Everyday examples: a moving average smooths a noisy temperature record (taps all equal), a canyon turns one shout into a train of fading echoes (taps are the echo strengths), a camera lens spreads a point of light into a small blob, which is a two-dimensional filter whose taps are that blob. Lecture 7 writes the causal prediction of an AR process as the filter $h_n$ applied to the past of $X_n$; lectures 12–13 write the imaging system as a blur filter $a_s$ applied to the unknown image. Reading those taps, where they sit and whether they are symmetric, is the first step of every derivation that follows.",
    check: {"question": "A filter has impulse response $h_n$. If the input is a single spike three samples late, $\\delta_{n-3}$, the output is:", "options": ["$h_{n-3}$: the same ring-out, started three samples later", "$h_n$: the filter ignores when the spike arrives", "$3h_n$", "$h_{n+3}$"], "answer": 0, "explain": "Time invariance: a delayed input gives the same output, delayed. This is exactly why the response to any input is a sum of shifted copies of $h_n$, i.e. a convolution."} },
  { id: 'fir-vs-iir', name: "FIR vs IIR: feed-forward vs feedback", group: 'Filters from scratch', lectures: [7], hook: "FIR: the output only remembers the last few inputs, like a moving average over the past week. IIR: the output feeds back into itself, like a bank balance earning interest or a cup of coffee cooling: one kick keeps echoing forever, fading if the feedback gain is below one.", bullets: ["FIR (finite impulse response): $y_n = \\sum_{k=0}^{P} b_k x_{n-k}$. The ring-out stops after $P$ samples. Always stable.", "IIR (infinite impulse response): $y_n = x_n + \\sum_{i\\ge1} h_i\\,y_{n-i}$. The output is recycled, so one spike never fully dies.", "AR(1): $X_n = \\rho X_{n-1} + E_n$ is white noise through an IIR filter with impulse response $\\rho^n$ ($n\\ge0$). It decays only if $|\\rho|<1$; that is the stability condition and also why $R_X(n) \\propto \\rho^{|n|}$.", "The whitening filter $\\delta_n - h_n$ is FIR with $P$ taps; its inverse $1/(1-H(\\omega))$ is the IIR synthesis filter (lecture 7)."], why: "Lecture 7 calls the AR model an IIR filter driven by white noise; the exam asks for $S_X$, which is just $|{\\rm IIR\\ response}|^2 \\cdot \\sigma_c^2$.", figure: 'fir-iir', videos: [{"id": "KuXjwB4LzSA", "title": "But what is a convolution?", "channel": "3Blue1Brown"}, {"search": "FIR vs IIR filter intuition", "note": "Look for a short explainer with block diagrams; the feedback loop is the whole idea."}], lesson: "Two families of filters appear in the course. A finite impulse response (FIR) filter forms its output only from the input and a bounded number of past inputs; feed it a spike and the output is nonzero for a finite number of samples, then exactly zero. The whitening filter $\\delta_n - h_n$ of lecture 7 is FIR: it subtracts a fixed, finite combination of past samples. An infinite impulse response (IIR) filter feeds its own output back, $y_n = x_n + \\sum_{i\\ge1} h_i y_{n-i}$, so a single spike produces a response that never fully stops. Lecture 7 points out that the AR model written forwards, $X_n = E_n + \\sum_i h_i X_{n-i}$, is exactly an IIR filter driven by white noise: the ‘white noise driven model’. For AR(1) the impulse response is $1, \\rho, \\rho^2, \\dots$, which decays when $|\\rho| < 1$ and blows up otherwise; the same geometric sequence shows up as the autocovariance $R_X(n) \\propto \\rho^{|n|}$. Everyday pictures of feedback: a savings account where this month’s balance is last month’s times $(1 + r)$ plus the deposit, or a room’s temperature that keeps a fraction of yesterday’s warmth. The two directions are inverses: analysis (FIR, $1 - H(\\omega)$) turns the coloured process into white noise, synthesis (IIR, $1/(1-H(\\omega))$) turns white noise back into the process.",
    check: {"question": "Which statement about $X_n = \\rho X_{n-1} + E_n$ is true?", "options": ["Its impulse response is $\\rho^n$ for $n \\ge 0$, so a single spike of $E$ keeps echoing with a factor $\\rho$ per step", "It is an FIR filter with one tap", "It is unstable for every $\\rho \\ne 0$", "Its impulse response is $\\delta_n - \\rho\\delta_{n-1}$"], "answer": 0, "explain": "Set $E_n = \\delta_n$: $X_0 = 1$, $X_1 = \\rho$, $X_2 = \\rho^2$, and so on. The last option is the whitening (inverse) filter, which is FIR."} },
  { id: 'lti-lsi', name: "LTI and LSI: why a filter has to be a convolution", group: 'Filters from scratch', lectures: [7, 13], hook: "Linear: double the input, double the output, and inputs add. Time-invariant (shift-invariant in images, LSI): the filter does not care what time it is or where in the picture it is. Those two rules alone force the filter to be a convolution with its impulse response. A guitar amp behaves the same at noon and at midnight; a lens blurs the same at every pixel.", bullets: ["Linearity: $x_1 \\to y_1$ and $x_2 \\to y_2$ imply $ax_1 + bx_2 \\to ay_1 + by_2$.", "Shift invariance: $x_{n-k} \\to y_{n-k}$ (1-D, LTI) or $x_{s-r} \\to y_{s-r}$ (2-D, LSI).", "Write $x_n = \\sum_k x_k\\delta_{n-k}$; each spike gives a shifted $h$, so $y_n = \\sum_k x_k h_{n-k} = (x*h)_n$.", "Lecture 13: an LSI blur $A$ acts as $Ax = a_s * x_s$ and $A^ty = a_{-s} * y_s$; in matrix form it is Toeplitz (constant diagonals)."], why: "The whole frequency analysis of gradient descent in lecture 13 rests on $A$ being LSI; without it there is no $h(\\omega)$.", figure: 'lti', videos: [{"id": "8rrHTtUzyZA", "title": "Convolutions in Image Processing (MIT 18.S191, Grant Sanderson)", "channel": "The Julia Programming Language"}, {"id": "KuXjwB4LzSA", "title": "But what is a convolution?", "channel": "3Blue1Brown"}], lesson: "Two properties define the systems the course cares about. Linearity means superposition: scaling the input scales the output and the response to a sum is the sum of the responses. Time invariance (called shift invariance, or LSI, for images) means the rule does not change with position: delay the input and the output is delayed by the same amount, nothing else changes. Together these give the central result: any input can be written as a sum of weighted spikes, $x_n = \\sum_k x_k\\delta_{n-k}$; each spike produces a shifted copy of the impulse response by shift invariance; the copies add by linearity; so the output is $y_n = \\sum_k x_k h_{n-k}$, the convolution of the input with the impulse response. There is no other possibility. Lecture 7 uses this to say that time-invariant causal prediction is convolution with $h_n$; lecture 13 uses it to say that an LSI blur matrix $A$ acts by convolution with $a_s$, its transpose by convolution with the space-reversed response $a_{-s}$, and that the matrix itself is Toeplitz, constant along diagonals. Where the assumption fails, at image boundaries or for a lens whose blur changes across the field, the neat frequency-domain picture fails with it.",
    check: {"question": "Which system is linear but not time-invariant?", "options": ["$y_n = n\\,x_n$: the gain depends on the clock", "$y_n = x_n - x_{n-1}$", "$y_n = 3x_{n-2}$", "$y_n = \\tfrac12(x_n + x_{n+1})$"], "answer": 0, "explain": "Multiplying by $n$ is linear, but a delayed input is not just a delayed output because the gain changed in between. The other three are convolutions with fixed taps (the last one is noncausal but still shift-invariant)."} },
  { id: 'frequency-response', name: "Frequency response: what a filter does to each frequency", group: 'Filters from scratch', lectures: [5, 7, 13], hook: "Feed a filter a pure tone and out comes the same tone, scaled and phase-shifted. The scale factor as a function of frequency, $|H(\\omega)|$, is the filter’s frequency response: the equalizer curve on a stereo. Bass boosted, treble cut.", bullets: ["Complex exponentials are eigenfunctions: $e^{j\\omega n} \\to H(\\omega)e^{j\\omega n}$ with $H(\\omega) = \\sum_n h_ne^{-j\\omega n}$, the DTFT of the taps.", "Convolution in time is multiplication in frequency: $Y(\\omega) = H(\\omega)X(\\omega)$; for random signals $S_Y = |H(\\omega)|^2S_X$.", "Averaging neighbours is low-pass (blur, smooth); differencing neighbours is high-pass (edges, noise). $\\tfrac12(\\delta_n+\\delta_{n-1})$ has $|H(\\pi)| = 0$: it kills the zigzag.", "Symmetric taps give a real $H(\\omega)$; that is why $g(\\omega)$ and $1 - g(\\omega)$ in the GMRF are real."], why: "Every spectrum on the midterm is a frequency response squared times a flat noise level, and every convergence-rate question reads $h(\\omega)$ off such a curve.", figure: 'freq-response', videos: [{"id": "spUNpyF58BY", "title": "But what is the Fourier Transform? A visual introduction.", "channel": "3Blue1Brown"}, {"id": "uihBwtPIBxM", "title": "Finding the Edges (Sobel Operator)", "channel": "Computerphile"}], lesson: "A linear shift-invariant filter cannot change the frequency of a pure tone; it can only change its amplitude and phase. The complex exponential $e^{j\\omega n}$ passes through the filter as $H(\\omega)e^{j\\omega n}$, where $H(\\omega) = \\sum_n h_ne^{-j\\omega n}$ is the discrete-time Fourier transform of the taps. This number, as a function of $\\omega$, is the frequency response, and the picture to keep is the equalizer on an audio system: a curve that says how much each band is boosted or cut. Because convolution becomes multiplication, filtering a signal multiplies its spectrum by $H(\\omega)$ and filtering a stationary random process multiplies its power spectral density by $|H(\\omega)|^2$ (lecture 5 and lecture 7, slide 12). Low-pass filters, such as any averaging of neighbours or any camera blur, have $|H|$ large near $\\omega = 0$ and small near $\\pi$; high-pass filters, such as differences of neighbours or edge detectors, do the opposite. Symmetric taps produce a real, even $H(\\omega)$, which is why the GMRF quantities $g(\\omega)$ and $1 - g(\\omega)$ are real and can be plotted on $[0, \\pi]$. In lecture 13 the same idea turns the Hessian of the MAP cost into a curve $h(\\omega) = |a(\\omega)|^2 + \\lambda(1 - g(\\omega))$ whose highest and lowest points control how fast gradient descent converges.",
    check: {"question": "The filter $h_n = \\tfrac12(\\delta_n + \\delta_{n-1})$ averages two neighbours. Its gain at the zigzag frequency $\\omega = \\pi$ is:", "options": ["$0$: an alternating $+1,-1,+1,\\dots$ input averages to nothing", "$1$: the same as at $\\omega = 0$", "$\\tfrac12$", "$2$"], "answer": 0, "explain": "$H(\\omega) = \\tfrac12(1 + e^{-j\\omega})$, so $H(\\pi) = \\tfrac12(1 - 1) = 0$. Averaging is low-pass: it passes slow patterns and removes the fastest one."} },
  { id: 'whitening-synthesis', name: "Whitening and synthesis: the two directions of the AR model", group: 'Filters from scratch', lectures: [5, 7], hook: "White noise is static: every frequency equally loud, nothing predictable from the past. Whitening a signal means subtracting everything you could have predicted, so only the surprise is left. Synthesis runs the same machine backwards: pour static into the feedback loop and the colour comes back.", bullets: ["Prediction error $E_n = X_n - \\sum_i h_iX_{n-i} = X_n * (\\delta_n - h_n)$: the FIR whitening filter (lecture 7).", "Its spectrum is flat: $S_E(\\omega) = |1-H(\\omega)|^2S_X(\\omega) = \\sigma_c^2$. Flat spectrum $=$ uncorrelated samples $=$ white.", "Synthesis: $X_n = E_n + \\sum_i h_iX_{n-i}$, white noise through the IIR filter $1/(1-H(\\omega))$, so $S_X = \\sigma_c^2/|1-H(\\omega)|^2$.", "‘Coloured noise’ just means white noise that went through a filter; the colour is $|1-H|^{-2}$."], why: "2021 Q3 and 2025 P1 are this picture: given $h$, write $S_X$; given $S_X$, read off the whitening filter.", figure: 'whiten-synth', videos: [{"id": "spUNpyF58BY", "title": "But what is the Fourier Transform? A visual introduction.", "channel": "3Blue1Brown"}, {"search": "whitening filter prediction error intuition", "note": "Search for “innovations” or “prediction error filter”; the AR synthesis/analysis pair is standard in DSP courses."}], lesson: "Lecture 7 reads the AR model in two directions. In the analysis direction the causal prediction $\\hat X_n = \\sum_i h_iX_{n-i}$ is subtracted from the sample, leaving the prediction error $E_n = X_n * (\\delta_n - h_n)$. Because the prediction error of a Gaussian AR process is independent of the past, these errors are uncorrelated from sample to sample: their autocovariance is $\\sigma_c^2\\delta_n$ and their spectrum is flat. A flat spectrum is what ‘white’ means, by analogy with white light containing all colours equally, and the FIR filter $\\delta_n - h_n$ is therefore called the whitening filter: it strips out everything predictable and keeps only the new information, the innovation. In the synthesis direction the equation is rearranged as $X_n = E_n + \\sum_i h_iX_{n-i}$, an IIR filter with frequency response $1/(1-H(\\omega))$ driven by white noise. Since filtering multiplies a spectrum by the squared magnitude of the response, $S_X(\\omega) = \\sigma_c^2/|1-H(\\omega)|^2$. The two filters are exact inverses, which is why the same $|1-H(\\omega)|^2$ appears in the denominator of $S_X$ and the numerator of $S_E$. Lecture 11 then shows that the noncausal (GMRF) description uses the symmetric filter $\\delta_n - g_n$ in the same role, with $1-G(\\omega) = |1-H(\\omega)|^2/r_0$.",
    check: {"question": "The prediction error $E_n$ of an AR process has power spectral density:", "options": ["A constant $\\sigma_c^2$ at every frequency", "$\\sigma_c^2/|1-H(\\omega)|^2$, the same as $X_n$", "$|1-H(\\omega)|^2$", "Zero, because the prediction is exact"], "answer": 0, "explain": "$E = (\\delta - h) * X$, so $S_E = |1-H|^2 S_X = |1-H|^2\\sigma_c^2/|1-H|^2 = \\sigma_c^2$. The error is white: nothing left to predict."} },
  { id: 'blur-inverse', name: "Blur, deconvolution, and why inverting a filter amplifies noise", group: 'Filters from scratch', lectures: [12, 13], hook: "A blur is a low-pass filter: it quietly erases the fine detail. Undoing it means dividing by $a(\\omega)$, which is tiny at high frequencies, so whatever noise lives there gets multiplied by a huge gain. It is like turning the treble all the way up on a hissy cassette: you recover a little detail and a lot of hiss.", bullets: ["Forward model (lecture 12): $Y = AX + W$ with $A$ an LSI blur, $Ax = a_s * x_s$, $W$ white noise.", "Maximum likelihood inverts $A$: $\\hat x(\\omega) = y(\\omega)/a(\\omega)$. Noise at frequency $\\omega$ is amplified by $1/|a(\\omega)|$, worst where the blur response is smallest. Condition number $\\kappa(A) = \\sigma_1/\\sigma_N$ measures the worst case.", "A GMRF prior adds $\\lambda(1-g(\\omega))$ to the denominator: at convergence of lecture 13’s update, $\\hat x(\\omega) = \\dfrac{a^*(\\omega)\\,y(\\omega)}{|a(\\omega)|^2 + \\lambda(1-g(\\omega))}$. Where the blur killed the signal, the prior takes over instead of the noise.", "$\\lambda = \\sigma^2/\\sigma_x^2$ is the noise-to-signal ratio: more noise, more smoothing."], why: "2021 Q2.3 asks exactly this: why does the ML estimate amplify noise, and how does the prior fix it.", figure: 'blur-inverse', videos: [{"id": "8rrHTtUzyZA", "title": "Convolutions in Image Processing (MIT 18.S191, Grant Sanderson)", "channel": "The Julia Programming Language"}, {"id": "uihBwtPIBxM", "title": "Finding the Edges (Sobel Operator)", "channel": "Computerphile"}], lesson: "Lecture 12 sets up image restoration as $Y = AX + W$: an unknown image $X$, a linear shift-invariant blur $A$ whose action is convolution with a point-spread function $a_s$, and additive white noise $W$. The blur is low-pass, so its frequency response $a(\\omega)$ is close to one for slow spatial patterns and close to zero for fine detail. The maximum-likelihood estimate ignores the noise and inverts the blur; in the frequency domain that is division by $a(\\omega)$. At the frequencies where $|a(\\omega)|$ is tiny the blurred signal was tiny too, but the noise was not, so the division multiplies noise by $1/|a(\\omega)|$ and the result is dominated by amplified hiss. The condition number $\\kappa(A) = \\sigma_1/\\sigma_N$, the ratio of the largest to smallest singular value, is the worst-case amplification. The MAP estimate adds a prior. With a homogeneous GMRF prior the cost is $\\tfrac12\\|y - Ax\\|^2 + \\tfrac{\\sigma^2}{2}x^tBx$, its Hessian in the frequency domain is $h(\\omega) = |a(\\omega)|^2 + \\lambda(1-g(\\omega))$ with $\\lambda = \\sigma^2/\\sigma_x^2$ (lecture 13), and setting the gradient to zero gives $\\hat x(\\omega) = a^*(\\omega)y(\\omega)/h(\\omega)$. The extra term $\\lambda(1 - g(\\omega))$ is largest exactly where $|a(\\omega)|^2$ is smallest, so the denominator never collapses: where the data cannot speak, the prior does. Turning $\\lambda$ up trades detail for noise suppression; $\\beta \\to 0$ recovers the noisy ML estimate and $\\beta \\to \\infty$ returns the prior’s own favourite image regardless of the data.",
    check: {"question": "Why does the maximum-likelihood estimate $\\hat x = A^{-1}y$ look so noisy for a blur $A$?", "options": ["Dividing by $a(\\omega)$ multiplies the noise by $1/|a(\\omega)|$, which is enormous at the high frequencies a blur suppresses", "Because the noise $W$ is not Gaussian", "Because $A^{-1}$ does not exist for any blur", "Because ML always underestimates the image"], "answer": 0, "explain": "The blur response is small near $\\omega = \\pi$; its inverse is large there. The signal at those frequencies was tiny after blurring, but the noise was not, so the inverse amplifies mostly noise. The prior term keeps the denominator away from zero."} },

  // ---- Signals and systems -------------------------------------------------
  { id: 'sequences-deltas', name: 'Sequences, deltas, shifts and symmetry', group: 'Signals and systems', lectures: [7, 10, 11], videos: [{"id": "1RIA9U5oXro", "title": "How Digital Audio Works", "channel": "Computerphile"}], hook: "A delta is a single Lego brick at one position. Every filter in this course is just a few bricks laid at chosen lags, so reading a filter means reading where the bricks are.", bullets: ["$\\delta_{n-k}$ is one brick at lag $k$; a filter is $h_n = \\sum_k h_k\\,\\delta_{n-k}$.", "Causal AR: bricks only at $k \\ge 1$, e.g. $h_n = \\rho\\,\\delta_{n-1}$.", "Symmetric GMRF: mirror bricks, $g_n = g_1(\\delta_{n-1}+\\delta_{n+1})$, nothing at $0$.", "Whitening filter $\\delta_n - h_n$: a brick of height $1$ at $0$, then $-h_k$ at each lag."], widget: 'delta-stack', why: "Every AR/GMRF question starts by writing $h_n$ or $g_n$ as deltas and then taking the DTFT term by term.", lesson: 'A discrete-time signal is a sequence $x_n$, $n\\in\\mathbb Z$. The Kronecker delta $\\delta_n$ is $1$ at $n=0$ and $0$ elsewhere, and $\\delta_{n-k}$ is a single spike at $n=k$. Every finite sequence is a sum of shifted deltas, $x_n = \\sum_k x_k\\,\\delta_{n-k}$, which is how the course writes filters: the AR(1) prediction filter is $h_n = \\rho\\,\\delta_{n-1}$ (one tap, one step in the past) and the order-1 GMRF predictor is $g_n = g_1(\\delta_{n-1}+\\delta_{n+1})$ (two taps, one on each side). The support is the set of $n$ with $x_n\\ne0$: support in $\\{1,\\dots,P\\}$ means causal (uses only the past), support in $\\{-P,\\dots,P\\}\\setminus\\{0\\}$ means noncausal and symmetric. A sequence is symmetric (even) if $x_{-n} = x_n$; the GMRF predictor and every autocorrelation are symmetric, the AR filter is not. Time reversal $x_{-n}$ flips the sequence about $n=0$. The prediction-error filter $\\delta_n - h_n$ has a $1$ at the origin followed by $-h_1, -h_2,\\dots$; applied to $X_n$ it whitens the process (lecture 7).',
    check: { question: 'The causal AR(2) prediction filter has taps $h_1$ and $h_2$. Which sequence is the prediction-error (whitening) filter $\\delta_n - h_n$?', options: ['$1$ at $n=0$, $-h_1$ at $n=1$, $-h_2$ at $n=2$, zero elsewhere', '$1$ at $n=0$, $h_1$ at $n=\\pm1$, $h_2$ at $n=\\pm2$', '$-h_1$ at $n=-1$, $-h_2$ at $n=-2$, zero elsewhere', '$1$ at every $n$ from $0$ to $2$'], answer: 0, explain: 'Causal taps sit at positive lags only, so $\\delta_n - h_n$ is $1$ at the origin and $-h_i$ at $n = i$ for $i = 1, 2$. The symmetric option is the shape of a GMRF predictor, not of an AR filter.' } },
  { id: 'complex-euler', name: 'Complex numbers and Euler’s formula', group: 'Signals and systems', lectures: [5, 7], hook: "$|1-\\rho e^{-j\\omega}|$ is just the distance between the point $1$ and a point running around a circle of radius $\\rho$. Closest at $\\omega = 0$ when $\\rho > 0$, farthest at $\\omega = \\pi$.", bullets: ["$e^{-j\\omega} = \\cos\\omega - j\\sin\\omega$, a point on the unit circle.", "$|z|^2 = z\\bar z = a^2 + b^2$.", "$|1-\\rho e^{-j\\omega}|^2 = 1 - 2\\rho\\cos\\omega + \\rho^2$ (the law of cosines in disguise)."], why: "This one expansion is the denominator of every AR power spectrum on the exam.", lesson: 'Euler: $e^{-j\\omega} = \\cos\\omega - j\\sin\\omega$. The squared modulus of $z = a + jb$ is $|z|^2 = z\\,\\bar z = a^2 + b^2$. So $|1-\\rho e^{-j\\omega}|^2 = (1-\\rho\\cos\\omega)^2 + (\\rho\\sin\\omega)^2 = 1 - 2\\rho\\cos\\omega + \\rho^2$, using $\\cos^2+\\sin^2 = 1$. This single expansion is the heart of every AR power-spectrum question.' },
  { id: 'dtft', name: 'DTFT of short sequences', group: 'Signals and systems', lectures: [5, 7], videos: [{"id": "spUNpyF58BY", "title": "But what is the Fourier Transform? A visual introduction.", "channel": "3Blue1Brown"}], dependsOn: ['complex-euler', 'sequences-deltas'], hook: "The DTFT asks each brick ‘how far do you delay?’ A delay of $k$ samples answers with a phase $e^{-j\\omega k}$. Add up the answers.", bullets: ["$H(\\omega) = \\sum_n h_n e^{-j\\omega n}$.", "$\\delta_{n-k} \\mapsto e^{-j\\omega k}$, so $\\rho\\,\\delta_{n-1} \\mapsto \\rho e^{-j\\omega}$.", "Mirror pair $g_1(\\delta_{n-1}+\\delta_{n+1}) \\mapsto 2g_1\\cos\\omega$: symmetric sequence, real transform."], why: "Needed to turn $h_n$ into $H(\\omega)$ before you can write $S_X(\\omega)$.", lesson: 'The DTFT is $H(\\omega) = \\sum_n h_n e^{-j\\omega n}$. A shifted delta transforms to a complex exponential: $\\delta(n-k) \\mapsto e^{-j\\omega k}$. Hence $h_n = \\rho\\,\\delta(n-1)$ gives $H(\\omega) = \\rho e^{-j\\omega}$, and the symmetric pair $g_1[\\delta(n-1)+\\delta(n+1)]$ gives $G(\\omega) = g_1(e^{-j\\omega}+e^{j\\omega}) = 2g_1\\cos\\omega$, which is real because the sequence is symmetric.' },
  { id: 'convolution', name: 'Convolution of deltas', group: 'Signals and systems', lectures: [7, 11], videos: [{"id": "KuXjwB4LzSA", "title": "But what is a convolution?", "channel": "3Blue1Brown"}], dependsOn: ['sequences-deltas'], hook: "Convolving two brick stacks: multiply every brick of one with every brick of the other and add the lags. Four bricks in, four terms out.", bullets: ["$f_n * \\delta_{n-k} = f_{n-k}$: a delta shifts.", "Linear, so expand products term by term.", "$(\\delta_n - \\rho\\delta_{n-1})*(\\delta_n - \\rho\\delta_{n+1}) = (1+\\rho^2)\\delta_n - \\rho\\delta_{n-1} - \\rho\\delta_{n+1}$.", "Convolution in time is multiplication in frequency."], why: "The AR-to-GMRF step is exactly one such convolution of the whitening filter with its mirror.", lesson: 'Convolution with a shifted delta shifts: $f_n * \\delta(n-k) = f_{n-k}$. Convolution is linear, so expand products term by term: $(\\delta_n - \\rho\\delta_{n-1}) * (\\delta_n - \\rho\\delta_{n+1}) = \\delta_n - \\rho\\delta_{n+1} - \\rho\\delta_{n-1} + \\rho^2\\delta_n$. In the frequency domain convolution becomes multiplication, which is why $|1-H(\\omega)|^2 = (1-H(\\omega))(1-H(\\omega))^*$ corresponds to $(\\delta_n-h_n)*(\\delta_n-h_{-n})$.' },
  { id: 'convolution-lsi', name: 'Convolution and linear shift-invariant filters', group: 'Signals and systems', lectures: [7, 13], figure: 'lti', videos: [{"id": "8rrHTtUzyZA", "title": "Convolutions in Image Processing (MIT 18.S191, Grant Sanderson)", "channel": "The Julia Programming Language"}], dependsOn: ['convolution'], hook: "Convolution is sliding a stencil over the signal: at every position multiply what you see by the stencil weights and add. Shift the signal, the output shifts along.", bullets: ["$(x*h)_n = \\sum_k h_k\\,x_{n-k}$; $\\delta_n$ is the identity.", "AR analysis: $E_n = X_n * (\\delta_n - h_n)$ whitens. Synthesis: $X_n = E_n + \\sum_{i\\ge1} h_i X_{n-i}$ is white noise through $1/(1-H(\\omega))$.", "LSI blur: $Ax = a_s * x_s$ and $A^ty = a_{-s} * y_s$ (reversed stencil).", "GMRF prior term: $\\sigma^2 Bx = \\lambda(\\delta_s - g_s) * x_s$ with $\\lambda = \\sigma^2/\\sigma_x^2$."], widget: 'convolve-stencil', why: "Lecture 13 writes the whole gradient step as three convolutions; exam pseudo-code questions expect that form.", lesson: 'The convolution of a signal with a filter is $(x*h)_n = \\sum_k h_k\\,x_{n-k}$: each output is a weighted sum of shifted copies of the input, with the weights read off the filter. It is linear, commutative and associative, $\\delta_n$ is the identity, and $x*\\delta_{n-k} = x_{n-k}$ is a pure shift. A system that computes a convolution is linear and time-invariant (1-D) or shift-invariant (2-D, LSI): shifting the input shifts the output. Lecture 7 reads the AR model both ways. Analysis: the prediction error $E_n = X_n - X_n*h_n = X_n*(\\delta_n-h_n)$ is the output of the whitening filter $1-H(\\omega)$. Synthesis: $X_n = E_n + \\sum_{i\\ge1}h_iX_{n-i}$ is an IIR filter $1/(1-H(\\omega))$ driven by white noise. The two filters are inverses. Lecture 13 uses the same idea for images: if $A$ is an LSI blur with impulse response $a_s$, then $Ax = a_s*x_s$ and the transpose is convolution with the space-reversed response, $A^ty = a_{-s}*y_s$; the GMRF prior term $\\sigma^2Bx$ becomes $\\lambda(\\delta_s-g_s)*x_s$ with $\\lambda=\\sigma^2/\\sigma_x^2$. So every matrix-vector product in the gradient is a few convolutions.',
    check: { question: 'For an LSI blur $A$ with impulse response $a_s$, the product $A^t y$ equals:', options: ['$a_{-s} * y_s$, convolution with the space-reversed response', '$a_s * y_s$, the same convolution as $Ay$', '$y_s / a_s$ pointwise', '$a_s * a_s * y_s$'], answer: 0, explain: 'Transposing a convolution matrix reverses the impulse response: $(A^t)_{s,r} = A_{r,s} = a_{r-s} = a_{-(s-r)}$. Lecture 13 writes the gradient step with $a_{-s}*(y - a_s*x)$ for exactly this reason.' } },
  { id: 'time-reversal', name: 'Time reversal and autocorrelation', group: 'Signals and systems', lectures: [5, 11], videos: [{"id": "KuXjwB4LzSA", "title": "But what is a convolution?", "channel": "3Blue1Brown"}], dependsOn: ['convolution', 'dtft'], hook: "Autocorrelation is a filter shaking hands with its own mirror image. The result is always symmetric and its spectrum is $|F(\\omega)|^2$, which can never be negative.", bullets: ["$f_{-n} \\mapsto F(\\omega)^*$ for real $f$.", "$f_n * f_{-n} \\mapsto |F(\\omega)|^2 \\ge 0$, symmetric in $n$.", "$(\\delta_n - h_n)*(\\delta_n - h_{-n})$ has support $[-P, P]$."], why: "This is why $1 - G(\\omega) = |1-H(\\omega)|^2 / r_0$ comes out real and nonnegative.", lesson: 'Time reversal $f_{-n}$ has DTFT $F(-\\omega) = F(\\omega)^*$ for real $f$. The autocorrelation $f_n * f_{-n}$ is symmetric and its DTFT is $|F(\\omega)|^2 \\ge 0$. For the AR filter, $(\\delta_n - h_n)*(\\delta_n-h_{-n})$ is the causal filter autocorrelated with itself; it is symmetric with support $[-P, P]$.' },
  { id: 'stationarity', name: 'Stationarity, autocovariance and white noise', group: 'Signals and systems', lectures: [5], hook: "Stationary means the rules do not change as you move along the axis. The whole process is then one curve, $R(n)$: how much do two samples $n$ apart still agree?", bullets: ["WSS: constant mean and $R(n,k) = R(n-k)$; for zero mean $R(n) = \\mathbb E[X_{k+n}X_k]$, $R(-n) = R(n)$, $R(0)$ is the variance.", "Gaussian: mean and $R$ specify everything, so WSS = strictly stationary.", "White noise: $R(n) = \\sigma^2\\delta_n$, flat spectrum $\\sigma^2$.", "Narrow $R$: fast-changing, power everywhere. Broad $R$: smooth, low-frequency power."], widget: 'ar-autocov', why: "The AR(1) variance $\\sigma_C^2/(1-\\rho^2)$ is $R(0)$, and $R(n) \\propto \\rho^{|n|}$ shows why the covariance matrix is full while $B$ is banded.", lesson: 'A random process is one random object with infinitely many coordinates $X_n$. It is wide-sense stationary (WSS) if its mean is constant and its autocovariance depends only on the lag: $R(n,k) = \\mathbb E[(X_n-\\mu)(X_k-\\mu)] = R(n-k)$. For a zero-mean process $R(n) = \\mathbb E[X_{k+n}X_k]$, $R(0)$ is the variance and $R(-n) = R(n)$. A Gaussian process is completely specified by its mean and autocovariance, so for Gaussian processes WSS is the same as strict stationarity, and a zero-mean stationary Gaussian process is specified by $R(n)$ alone, or equivalently by its power spectral density (lecture 5). White noise is the simplest case: $R(n) = \\sigma^2\\delta_n$, samples uncorrelated (independent when Gaussian), flat spectrum $S(\\omega) = \\sigma^2$. Shape intuition: a narrow $R(n)$ (correlation dies in a few samples) means a fast-changing process whose power spreads over all frequencies; a broad $R(n)$ means a smooth process with its power at low frequencies. Stationary Gaussian processes are also reversible: $X_{-n}$ has the same distribution as $X_n$, because reversal leaves the autocovariance unchanged.',
    check: { question: 'A zero-mean process has autocovariance $R(n) = 3\\,\\delta_n$. Which statement is true?', options: ['It is white noise with variance 3 and flat power spectral density $S(\\omega) = 3$', 'It is a smooth, low-pass process', 'Its variance is $3/2$ because $R$ is symmetric', 'It cannot be stationary because $R$ is zero for $n\\ne0$'], answer: 0, explain: 'An autocovariance that is a scaled delta means uncorrelated samples of variance $R(0) = 3$. The DTFT of $3\\delta_n$ is the constant $3$: equal power at every frequency, which is what white means.' } },
  { id: 'psd', name: 'Power spectral density (Wiener–Khinchin)', group: 'Signals and systems', lectures: [5, 7], figure: 'freq-response', dependsOn: ['stationarity', 'dtft', 'time-reversal'], hook: "The PSD is the variance split up by frequency: a budget that says where the wiggles live. A filter reshapes the budget by $|A(\\omega)|^2$.", bullets: ["$S_X(\\omega) = \\sum_n R(n)e^{-j\\omega n}$; its average over $\\omega$ is $R(0)$.", "White noise: $S_E = \\sigma^2$, flat.", "Filtering: $S_Y = |A(\\omega)|^2 S_X$. Squared, because power is amplitude squared.", "AR: $S_X = \\sigma_C^2 / |1-H(\\omega)|^2$; GMRF: $S_X = \\sigma_{NC}^2/(1-G(\\omega))$."], why: "Every midterm since 2021 has asked for $S_X(\\omega)$ of a given AR or GMRF model.", lesson: 'Three facts chain together. (1) What a PSD is: a zero-mean stationary process has variance $R(0)$, and $S_X(\\omega) = \\sum_n R_X(n)e^{-j\\omega n}$ (the DTFT of the autocovariance, lecture 5 slide 13) spreads that variance over frequency; averaging $S_X$ over $\\omega\\in[-\\pi,\\pi]$ gives back $R(0)$. (2) White noise is flat: uncorrelated samples mean $R_E(n) = \\sigma_C^2\\delta_n$, and the DTFT of a delta is 1, so $S_E(\\omega) = \\sigma_C^2$ at every frequency. (3) A filter multiplies the PSD by its squared magnitude: if $Y = a*E$ then $R_Y = a_n*a_{-n}*R_E$ (the time-reversed copy appears because the autocovariance pairs the signal with a shifted copy of itself), and transforming gives $S_Y = A(\\omega)A(\\omega)^*S_E = |A(\\omega)|^2S_E$. Squared, not first power, because power is amplitude squared and phase carries no power. The AR model $(\\delta_n-h_n)*X_n = E_n$ says $X$ is white noise through $A(\\omega) = 1/(1-H(\\omega))$, hence $S_X(\\omega) = \\sigma_C^2/|1-H(\\omega)|^2$. Reading the same equation backwards, $E = (\\delta-h)*X$ is the whitening direction with $S_E = |1-H|^2S_X = \\sigma_C^2$. Check with $\\rho = 0.5$, $\\sigma_C^2 = 1$: $S_X(0) = 1/0.25 = 4$, $S_X(\\pi) = 1/2.25 = 0.444$, and the average over $\\omega$ is $\\sigma_C^2/(1-\\rho^2) = 1.333$, the known AR(1) variance.' },
  { id: 'spectrum-reading', name: 'Reading a spectrum: ω = 0, ω = π, low-pass and high-pass', group: 'Signals and systems', lectures: [5, 7, 13], videos: [{"id": "spUNpyF58BY", "title": "But what is the Fourier Transform? A visual introduction.", "channel": "3Blue1Brown"}], dependsOn: ['psd'], hook: "$\\omega = 0$ is a flat line, $\\omega = \\pi$ is the zigzag $+,-,+,-$. A spectrum tells you which pattern the process prefers; a Hessian spectrum tells you which pattern converges last.", bullets: ["Symmetric filter: real, even response. Plot $[0,\\pi]$ only.", "AR(1): $\\rho > 0$ peaks at $0$ (smooth, low-pass); $\\rho < 0$ peaks at $\\pi$ (zigzag, high-pass).", "$h(\\omega) = |a(\\omega)|^2 + \\lambda(1-g(\\omega)) > 0$: eigenvalues of $H$.", "Mode at $\\omega$ decays as $(1-\\alpha h(\\omega))^k$: smallest $h$ converges last. Example 5.1: $h_{\\max}=4$, $h_{\\min}=1/5$, $\\kappa = 20$."], widget: 'ar-spectrum', why: "2023 P2 and 2024 P1 ask which frequencies converge slowly and how many iterations they need.", lesson: 'Frequency $\\omega$ is in radians per sample. $\\omega = 0$ is the constant (DC) pattern, $\\omega = \\pi$ is the fastest pattern a sampled signal can hold, the alternation $(-1)^n$. A real symmetric filter has a real, even frequency response, $g(\\omega) = g(-\\omega)$, so plots run over $[0,\\pi]$ only. For AR(1), $|1-\\rho e^{-j\\omega}|^2 = 1-2\\rho\\cos\\omega+\\rho^2$ is smallest at $\\omega=0$ when $\\rho>0$, so $S_X$ peaks at DC: a low-pass, smooth process. For $\\rho<0$ the peak moves to $\\pi$: high-pass, sample paths that alternate. The same reading explains convergence in lecture 13. With an LSI blur and a homogeneous GMRF prior, the Hessian eigenvalues are $h(\\omega) = |a(\\omega)|^2 + \\lambda(1-g(\\omega))$. A blur is low-pass, so $|a(\\omega)|^2$ is large at $\\omega=0$ and small near $\\pi$; $1-g(\\omega)$ is $0$ at $\\omega=0$ and largest at $\\pi$, so $h(\\omega)>0$ everywhere. Each error mode decays as $(1-\\alpha h(\\omega))^k$, so the frequencies with the smallest $h(\\omega)$ converge last. In Example 5.1 the extremes are $h_{\\max} = 4$ and $h_{\\min} = 1/5$, so $\\kappa = 20$, and with $\\alpha = 1/h_{\\max}$ the slowest mode decays as $(1-1/20)^k$: about $90$ iterations to reach $1\\%$, and those slow modes are the edges.',
    check: { question: 'In an AR(1) model with $\\rho = -0.8$ and $\\sigma_C^2 = 1$, where is the power spectral density largest?', options: ['At $\\omega = \\pi$: the process is high-pass and its sample paths alternate in sign', 'At $\\omega = 0$: every AR(1) process is low-pass', 'At $\\omega = \\pi/2$', 'It is flat because $|\\rho| < 1$'], answer: 0, explain: '$S_X(\\omega) = 1/(1 - 2\\rho\\cos\\omega + \\rho^2)$. With $\\rho<0$ the denominator $1+1.6\\cos\\omega+0.64$ is smallest at $\\cos\\omega = -1$, i.e. $\\omega = \\pi$, where $S_X = 1/0.04 = 25$. Negative $\\rho$ means each sample tends to have the opposite sign of the previous one.' } },
  { id: 'toeplitz-circulant', name: 'Toeplitz and circulant matrices, the DFT and eigenvalues', group: 'Signals and systems', lectures: [7, 8, 13], figure: 'toeplitz', videos: [{"id": "nmgFG7PUHfo", "title": "The Most Underrated Algorithm (the FFT)", "channel": "Veritasium"}], dependsOn: ['convolution-lsi', 'eigenvalues'], hook: "A circulant matrix is a convolution wearing a matrix costume. Take the costume off with the DFT and it becomes plain multiplication: the eigenvalues are the frequency response.", bullets: ["Toeplitz $A_{ij} = a_{i-j}$: convolution with truncated edges. Circulant $A_{ij} = a_{(i-j)\\bmod N}$: circular convolution.", "Eigenvectors $e^{j\\omega_k n}$, $\\omega_k = 2\\pi k/N$; eigenvalues $a(\\omega_k)$ = DFT of the first column.", "So $H = A^tA + \\lambda(I-G)$ has eigenvalues $h(\\omega) = |a(\\omega)|^2 + \\lambda(1-g(\\omega))$ and $\\kappa = h_{\\max}/h_{\\min}$.", "2-D raster order: Toeplitz-block-Toeplitz, DSFT instead of DFT."], widget: 'circulant-dft', why: "Lets you answer ‘what are the eigenvalues of $H$’ with a plot instead of a matrix.", lesson: 'A matrix with constant diagonals, $A_{ij} = a_{i-j}$, is Toeplitz; multiplying by it is convolution with truncated boundaries (lecture 7). If the diagonals wrap around, $A_{ij} = a_{(i-j)\\bmod N}$, the matrix is circulant and multiplying by it is circular convolution, which the discrete Fourier transform turns into multiplication. Concretely, the complex exponentials $e^{j\\omega_kn}$ with $\\omega_k = 2\\pi k/N$ are the eigenvectors of every circulant matrix, and the eigenvalue of the $k$-th one is the DFT of the first column, $a(\\omega_k) = \\sum_n a_ne^{-j\\omega_kn}$. A symmetric $a_n$ gives real eigenvalues. This is why lecture 13 can write the eigenvalues of $H = A^tA + \\lambda(I-G)$ as the function $h(\\omega) = |a(\\omega)|^2 + \\lambda(1-g(\\omega))$ when $A$ is an LSI blur and the prior is a homogeneous GMRF: the eigen-decomposition is the Fourier transform, $h_{\\max}$ and $h_{\\min}$ are the extremes of the plot, and $\\kappa = h_{\\max}/h_{\\min}$. In 2-D, stacking the image in raster order turns a shift-invariant filter into a Toeplitz-block-Toeplitz matrix (lectures 8 and 10) and the DSFT plays the role of the DFT.',
    check: { question: 'A circulant $N\\times N$ matrix has first column $a_n$. Its eigenvalues are:', options: ['The DFT values $a(\\omega_k) = \\sum_n a_ne^{-j\\omega_kn}$, $\\omega_k = 2\\pi k/N$', 'The entries $a_n$ themselves', 'All equal to $\\sum_n a_n$', 'The squared entries $a_n^2$'], answer: 0, explain: 'Circular convolution of $e^{j\\omega_kn}$ with $a$ returns $a(\\omega_k)e^{j\\omega_kn}$, so the exponentials are eigenvectors with the DFT of $a$ as eigenvalues. Only the $k=0$ eigenvalue equals $\\sum_n a_n$.' } },
  { id: 'dsft-2d', name: '2-D signals: random fields, the DSFT and the (2P+1)×(2P+1) window', group: 'Signals and systems', lectures: [5, 8, 10], dependsOn: ['stationarity', 'dtft'], hook: "An image is a signal with two indices. Nothing new happens: every formula just grows a second $\\omega$, and the window around a pixel becomes a square.", bullets: ["Lattice $S = \\{1..N\\}^2$, $s = (s_1, s_2)$; raster order stacks rows into one vector.", "2-D PSD: $S_X(e^{j\\omega_1}, e^{j\\omega_2}) = \\sum_s R(s)e^{-j(\\omega_1 s_1 + \\omega_2 s_2)}$, the DSFT.", "Order-$P$ window: $(2P+1)^2 - 1$ neighbours ($8$, $24$); the AR model keeps only the raster past.", "Everything 1-D carries over with 2-D convolution and the DSFT."], widget: 'neighbor-window', why: "Counting neighbours and recognising ‘formally identical to 1-D’ is what the 2-D parts of lectures 8 and 10 test.", lesson: 'An image is a signal on the lattice $S = \\{1,\\dots,N\\}^2$ with pixel index $s = (s_1,s_2)$. Raster order stacks the rows into one vector, $X = [X_{1,1},\\dots,X_{1,N},X_{2,1},\\dots,X_{N,N}]^t$, so matrix formulas apply unchanged; for an AR model raster order also decides which pixels count as the past, for a GMRF it only says where a pixel sits in the vector (lecture 10). A random field is 2-D stationary when every shifted window has the same distribution; its autocovariance $R(s_1,s_2)$ depends on the 2-D lag, and its power spectral density is the discrete-space Fourier transform, $S_X(e^{j\\omega_1},e^{j\\omega_2}) = \\sum_{s}R(s)\\,e^{-j(\\omega_1s_1+\\omega_2s_2)}$ (lecture 5). Every 1-D result of the course carries over with 2-D convolution in place of 1-D convolution and the DSFT in place of the DTFT. The noncausal neighborhood of order $P$ is the square window $\\partial s = \\{r\\ne s: |r_1-s_1|\\le P,\\ |r_2-s_2|\\le P\\}$ with $(2P+1)^2-1$ neighbors: $8$ for $P=1$, $24$ for $P=2$. The 2-D AR window keeps only the half of that square that precedes $s$ in raster order.',
    check: { question: 'How many neighbors does a pixel have in a 2-D GMRF of order $P = 1$, and in the corresponding 2-D causal AR model?', options: ['$8$ neighbors for the GMRF; the AR model uses the $4$ that come earlier in raster order', '$4$ for the GMRF and $2$ for the AR model', '$9$ for the GMRF and $9$ for the AR model', '$8$ for both'], answer: 0, explain: 'The $3\\times3$ window minus the center has $8$ pixels. In raster order the pixels above $s$ and the one to its left come first: the row above contributes $3$ and the current row $1$, which is $4$ (lecture 8). The GMRF is symmetric and uses all $8$.' } },

  // ---- Probability and Gaussian models --------------------------------------
  { id: 'gaussian-density', name: 'Multivariate Gaussian density', group: 'Probability and Gaussian models', lectures: [6, 9], videos: [{"id": "HZGCoVF3YvM", "title": "Bayes theorem, the geometry of changing beliefs", "channel": "3Blue1Brown"}], hook: "A Gaussian is a bowl-shaped hill over $\\mathbb R^N$. The precision matrix $B$ sets the bowl’s shape, and a zero in $B$ means two coordinates never pull on each other directly.", bullets: ["$p(x) = (2\\pi)^{-N/2}|B|^{1/2}\\exp\\{-\\tfrac12 x^tBx\\}$ with $B = R^{-1}$.", "$x^tBx$ couples $x_i, x_j$ only through $B_{ij}$.", "$B_{ij} = 0 \\iff X_i \\perp X_j$ given the rest."], why: "Writing the density of a GMRF from $B$ is a one-line exam part if you know this form.", lesson: 'A zero-mean Gaussian vector with covariance $R$ has $p(x) = (2\\pi)^{-N/2}|B|^{1/2}\\exp(-\\tfrac12 x^tBx)$ with $B = R^{-1}$, the precision matrix. The quadratic form $x^tBx$ couples $x_i$ and $x_j$ only through $B_{ij}$; if $B_{ij} = 0$ then $X_i$ and $X_j$ are conditionally independent given the rest.' },
  { id: 'precision-matrix', name: 'Precision matrix and conditionals', group: 'Probability and Gaussian models', lectures: [9, 10, 11], figure: 'graph-mrf', dependsOn: ['gaussian-density'], hook: "Row $s$ of $B$ is the recipe for predicting pixel $s$ from everyone else: divide the row by its diagonal and flip the sign.", bullets: ["$B = \\Gamma^{-1}(I-G)$.", "$\\sigma_s^2 = 1/B_{ss}$, $g_{s,r} = -B_{s,r}/B_{ss}$ (mind the minus).", "$\\mathbb E[X_s | \\text{rest}] = \\sum_{r\\ne s} g_{s,r}X_r$."], why: "2021 Q3.6 and 2022 Q2 ask you to read the predictor and its variance straight off $B$, including boundary rows.", lesson: 'From $B = \\Gamma^{-1}(I-G)$: $\\sigma_n^2 = 1/B_{nn}$ and $g_{n,i} = -B_{n,i}/B_{n,n}$ for $i\\ne n$. The conditional mean of $X_n$ given the others is $\\sum_{i\\ne n} g_{n,i}X_i = -\\sum_{i \\ne n}(B_{n,i}/B_{n,n})X_i$. Reading $B$ row by row therefore tells you the noncausal predictor and its variance.' },

  // ---- Linear algebra and calculus -------------------------------------------
  { id: 'matrix-calculus', name: 'Gradients of quadratic forms', group: 'Linear algebra and calculus', lectures: [12, 13, 14], videos: [{"id": "IHZwWFHWa-w", "title": "Gradient descent, how neural networks learn", "channel": "3Blue1Brown"}], hook: "Differentiating a quadratic is like differentiating $\\tfrac12 ax^2$: you get ‘the matrix times $x$’, and the only thing to get right is the sign from the inner minus.", bullets: ["$\\nabla_x \\tfrac12\\|y-Ax\\|^2 = -A^t(y-Ax)$.", "$\\nabla_x \\tfrac12 x^tBx = Bx$ for symmetric $B$.", "Hessian of the MAP cost: $A^tA + B$; set $\\nabla = 0$ for the closed form."], why: "Every gradient-descent, line-search and ICD derivation starts from these two lines.", lesson: '$\\nabla_x \\tfrac12\\|y-Ax\\|^2 = -A^t(y-Ax)$ and $\\nabla_x \\tfrac12 x^tBx = Bx$ for symmetric $B$. The Hessian of $\\tfrac12\\|y-Ax\\|^2 + \\tfrac12 x^tBx$ is $A^tA + B$. Setting the gradient to zero gives the Gaussian MAP estimate.' },
  { id: 'eigenvalues', name: 'Eigenvalues and bounding quadratic forms', group: 'Linear algebra and calculus', lectures: [13, 19], videos: [{"id": "IHZwWFHWa-w", "title": "Gradient descent, how neural networks learn", "channel": "3Blue1Brown"}], hook: "Eigenvalues are the stiffness of a bowl in each direction. A scalar $a$ bounds the whole bowl exactly when it beats the stiffest direction.", bullets: ["$\\lambda_{\\min}\\|x\\|^2 \\le x^tMx \\le \\lambda_{\\max}\\|x\\|^2$ for symmetric $M$.", "$aI \\succeq A^tA \\iff a \\ge \\lambda_{\\max}(A^tA)$.", "Gradient descent is stable iff $0 < \\alpha < 2/\\lambda_{\\max}(H)$."], why: "This is how the quadratic surrogate of $\\tfrac12\\|y-Ax\\|^2$ with curvature $a$ is justified (2022 Q4).", lesson: 'For symmetric $M$, $\\lambda_{\\min}\\|x\\|^2 \\le x^tMx \\le \\lambda_{\\max}\\|x\\|^2$. So $aI \\succeq A^tA$ holds exactly when $a \\ge \\lambda_{\\max}(A^tA)$; this is how a quadratic surrogate with scalar curvature is justified.' },
  { id: 'calculus-1d', name: '1-D derivatives and convexity', group: 'Linear algebra and calculus', lectures: [17, 18, 19], figure: 'bowl', hook: "A surrogate is a parabola that kisses the curve at $x'$: same height, same slope, and stiff enough to stay above it.", bullets: ["Convex on an interval $\\iff f'' \\ge 0$ there.", "Touch: $q(x';x') = f(x')$, $q'(x';x') = f'(x')$.", "Dominate: curvature $a \\ge \\max f''$ on the region of interest."], why: "Surrogate questions (2021 Q4, 2023 P3, 2024 P2) are graded on exactly these three checks.", lesson: 'A twice-differentiable $f$ is convex on an interval iff $f^{\\prime\\prime} \\ge 0$ there. A quadratic surrogate at $x^\\prime$ matches the value and the slope: $q(x^\\prime;x^\\prime) = f(x^\\prime)$ and $q^\\prime(x^\\prime;x^\\prime) = f^\\prime(x^\\prime)$; its curvature must dominate $f^{\\prime\\prime}$ on the region of interest.' },
  { id: 'sketching', name: 'Sketching functions for exam answers', group: 'Linear algebra and calculus', lectures: [16, 18, 19, 23], dependsOn: ['calculus-1d'], hook: "Graders look for shape and labels, not accuracy: kinks, flat parts, where two curves touch. There are only five shapes to learn.", bullets: ["Potentials: bowl $\\Delta^2/2$; V-shape $|\\Delta|$; Huber = bowl inside $\\pm T$, lines of slope $\\pm T$ outside, no corner at the join.", "Influence $\\rho'$: line; sign step; clip saturating at $\\pm T$.", "Surrogate: parabola touching $f$ at $x'$, above elsewhere. Label $x'$, $\\arg\\min q$, $\\arg\\min f$.", "Shrinkage $S_\\lambda$: zero on $[-\\lambda,\\lambda]$, slope $1$ outside."], widget: 'sketch-gallery', why: "2023 P3 and 2024 P2 ask for sketches; the labels are where the points are.", lesson: 'Exam sketches are graded on shape and labels, not on accuracy. Potential functions (lecture 16): the quadratic $\\Delta^2/2$ is a bowl; $|\\Delta|$ is a V with a kink at $0$; the Huber function $\\rho_T$ is the bowl $\\Delta^2/2$ for $|\\Delta|<T$ continued by straight lines of slope $\\pm T$ outside, joined with matching slope so there is no corner. Their influence functions $\\rho^\\prime$ are a line through the origin, a step of height $\\pm1$, and the clip $\\mathrm{clip}\\{\\Delta,[-T,T]\\}$, a line that saturates at $\\pm T$: mark $T$ on both axes. A surrogate sketch (lectures 18–19) shows the curve $f$, the parabola $q(x;x^\\prime)$ touching it at $x^\\prime$ and lying above it everywhere else; label $x^\\prime$, the minimizer of $q$ (the next iterate) and the minimizer of $f$, and show that the iterate moves toward the latter. For $|x|$ the surrogate is $x^2/(2|x^\\prime|)+|x^\\prime|/2$, which touches the V at $\\pm x^\\prime$. The shrinkage function $S_\\lambda(y)$ (lecture 23) is zero on $[-\\lambda,\\lambda]$ and continues with slope $1$ outside, so it is the identity line pushed down by $\\lambda$ on the right and up by $\\lambda$ on the left: mark $\\pm\\lambda$ on the $y$ axis. Always draw and label the axes, the key constants ($T$, $\\lambda$, $x^\\prime$) and the touching point.',
    check: { question: 'Which sketch of the Huber influence function $\\rho_T^\\prime(\\Delta)$ is correct?', options: ['A line of slope 1 through the origin that saturates at $+T$ for $\\Delta\\ge T$ and at $-T$ for $\\Delta\\le -T$', 'A step from $-1$ to $+1$ at $\\Delta = 0$', 'A parabola with its minimum at $\\Delta = 0$', 'A line of slope 1 through the origin with no saturation'], answer: 0, explain: 'Inside $|\\Delta|<T$ the Huber function is $\\Delta^2/2$ with derivative $\\Delta$; outside it is $T|\\Delta| - T^2/2$ with derivative $\\pm T$. So the influence is the clip function. The step is the influence of $|\\Delta|$, the unbounded line is the influence of the quadratic.' } },

  // ---- Graphs and Markov random fields ---------------------------------------
  { id: 'neighborhood-cliques', name: 'Neighborhood systems and pairwise cliques', group: 'Graphs and Markov random fields', lectures: [10, 15], figure: 'graph-mrf', videos: [{"search": "Markov random field image prior intuition"}], hook: "Pixels are people and neighbours are friends: friendship is mutual and you are not your own friend. A pairwise clique is one friendship, counted once.", bullets: ["Rules: $s \\notin \\partial s$ and $s \\in \\partial r \\iff r \\in \\partial s$.", "Cliques $\\mathcal P = \\{\\{s,r\\}: r \\in \\partial s\\}$ = the edge set, each edge once.", "1-D order $P$: $2P$ neighbours. 2-D: $(2P+1)^2 - 1$.", "$\\sum_s\\sum_{r\\in\\partial s}$ visits each edge twice; that is where the $\\tfrac12$ comes from."], widget: 'neighbor-graph', why: "Defining the neighbourhood correctly (symmetric, no self) is the first line of any MRF proof.", lesson: 'Think of the pixels $s\\in S$ as the vertices of an undirected graph. A neighborhood system assigns to each pixel a set $\\partial s\\subset S$ subject to two rules (book Definition 4.2): a pixel is not its own neighbor, $s\\notin\\partial s$, and neighborliness is symmetric, $s\\in\\partial r \\iff r\\in\\partial s$. The edges of the graph are the neighbor pairs. A pairwise clique is an unordered pair $\\{s,r\\}$ with $r\\in\\partial s$, and $\\mathcal P$ is the set of all of them, so $\\mathcal P$ is exactly the edge set and each edge appears once (lecture 15). In 1-D the order-$P$ system is $\\partial n = \\{n\\pm1,\\dots,n\\pm P\\}$ with $2P$ neighbors; in 2-D it is the $(2P+1)\\times(2P+1)$ window minus the center. Counting matters: a double sum $\\sum_s\\sum_{r\\in\\partial s}$ visits every edge twice, once from each end, while a sum over $\\{s,r\\}\\in\\mathcal P$ visits it once. That is where the factor $\\tfrac12$ comes from when a quadratic form is rewritten over cliques, and it is why the conditional of $X_s$ involves only the cliques containing $s$, i.e. the edges at vertex $s$.',
    check: { question: 'A 1-D GMRF of order $P = 2$ on $N$ samples. Which set is a valid neighborhood of $n$ (away from the boundary)?', options: ['$\\partial n = \\{n-2, n-1, n+1, n+2\\}$', '$\\partial n = \\{n-2, n-1, n\\}$', '$\\partial n = \\{n-2, n-1, n, n+1, n+2\\}$', '$\\partial n = \\{n-1, n-2\\}$ only, because the model is causal'], answer: 0, explain: 'A neighborhood excludes the pixel itself and must be symmetric: if $n-1\\in\\partial n$ then $n\\in\\partial(n-1)$, which forces $n+1\\in\\partial n$ for a homogeneous system. The one-sided sets describe the causal AR window, which is not a neighborhood system.' } },
  { id: 'mrf-markov', name: 'The Markov property and the zero pattern of B', group: 'Graphs and Markov random fields', lectures: [9, 10, 15], videos: [{"search": "Markov random fields conditional independence precision matrix"}], dependsOn: ['neighborhood-cliques', 'precision-matrix'], hook: "Markov: once you know your neighbours, the rest of the image is gossip you do not need. $B$ lists the direct friendships; the covariance mixes in every gossip chain, so it is full.", bullets: ["MRF: $p(x_s | x_{r\\ne s}) = p(x_s | x_{\\partial s})$.", "GMRF $\\iff$ $B_{s,r} = 0$ for $r \\notin \\partial s \\cup \\{s\\}$: the graph is the sparsity of $B$, not of $R$.", "Read off: $\\sigma_s^2 = 1/B_{ss}$, $g_{s,r} = -B_{s,r}/B_{ss}$.", "Proof pattern: factor $p(x)$ = (cliques at $s$) × (rest); the rest cancels in the conditional."], widget: 'neighbor-precision', why: "‘Show that this distribution is an MRF’ is a standard part; the factor-and-cancel pattern is the whole answer.", lesson: 'A random field with neighborhood system $\\partial s$ is a Markov random field (MRF) if the conditional distribution of each pixel given all the others depends only on its neighbors: $p(x_s|x_{r\\ne s}) = p(x_s|x_{\\partial s})$ (lecture 15). For a Gaussian field this is a statement about the precision matrix, not the covariance: $X$ is a GMRF with neighborhood $\\partial s$ exactly when $B_{s,r} = 0$ for $r\\notin\\partial s\\cup\\{s\\}$, so the graph is the sparsity pattern of $B = R^{-1}$, while $R$ itself is in general full (lectures 9–10). Read the predictor off the rows of $B$: $\\sigma_s^2 = 1/B_{s,s}$ and $g_{s,r} = -B_{s,r}/B_{s,s}$, with the minus sign, so a positive off-diagonal entry of $B$ means a negative prediction weight. To prove that a distribution is an MRF, factor $p(x)$ into the part that contains $x_s$, which is the product over the cliques at $s$, times a function of the other pixels; in the conditional the second factor and the partition function cancel, leaving a function of $x_s$ and $x_{\\partial s}$ only. The argument never uses the form of the potential, so every pairwise Gibbs distribution is an MRF.',
    check: { question: 'For a GMRF, which matrix has zeros exactly where two pixels are not neighbors?', options: ['The precision matrix $B = R^{-1}$', 'The covariance matrix $R$', 'Both $R$ and $B$', 'Neither; the neighborhood is a property of the mean'], answer: 0, explain: 'The conditional of $X_s$ depends on $x_r$ only through $B_{s,r}x_sx_r$ in the exponent, so $B_{s,r} = 0$ removes the dependence. Covariances of an AR(1) decay like $\\rho^{|n|}$ and never vanish, yet the precision matrix is tridiagonal.' } },
  { id: 'gibbs-energy', name: 'Gibbs distributions: energy over cliques, potentials and the partition function', group: 'Graphs and Markov random fields', lectures: [15, 16], figure: 'springs', dependsOn: ['neighborhood-cliques', 'gaussian-density'], hook: "Think springs: every edge is a spring between two pixels, with energy $\\rho$ of its stretch. The most likely image is the one where all the springs balance.", bullets: ["$p(x) = \\tfrac1z\\exp\\{-\\sum_{\\{s,r\\}\\in\\mathcal P} b_{s,r}\\,\\rho(x_s - x_r)\\}$, $z = \\int e^{-u(x)}dx$.", "GMRF: $x^tBx = \\sum_s a_s x_s^2 + \\sum_{\\mathcal P} b_{s,r}(x_s - x_r)^2$, $b_{s,r} = -B_{s,r}$.", "Force balance for one pixel: $\\sum_{r\\in\\partial s} b_{s,r}\\rho'(\\hat x_s - x_r) = 0$; $\\rho'$ is the influence function.", "Quadratic: unbounded force, edges smoothed. $|\\Delta|$ or Huber: bounded force, edges survive."], widget: 'force-balance', why: "Explains in one picture why the course leaves the GMRF for Huber and TV priors (lectures 15–16).", lesson: 'A pairwise Gibbs distribution is $p(x) = \\tfrac1z\\exp\\{-\\sum_{\\{s,r\\}\\in\\mathcal P}b_{s,r}\\,\\rho(x_s-x_r)\\}$: the energy is a sum over the edges of the graph of a potential $\\rho$ of the pixel difference, weighted by $b_{s,r}\\ge0$, and the partition function $z = \\int\\exp\\{-u(x)\\}dx$ is whatever constant makes it integrate to one (lecture 15). The GMRF is the special case $\\rho(\\Delta) = \\Delta^2/2$, because for any symmetric $B$, $x^tBx = \\sum_s a_sx_s^2 + \\sum_{\\{s,r\\}\\in\\mathcal P}b_{s,r}(x_s-x_r)^2$ with $b_{s,r} = -B_{s,r}$ and $a_s = \\sum_rB_{s,r}$, which for a homogeneous GMRF equals $(1-\\sum_rg_r)/\\sigma_{NC}^2$. The potential is the energy of one edge and its derivative $\\rho^\\prime$ is the influence function, the force a neighbor exerts: the most probable value of a pixel given its neighbors solves the force balance $\\sum_{r\\in\\partial s}b_{s,r}\\rho^\\prime(\\hat x_s-x_r) = 0$. With the quadratic potential the forces grow without bound, so one pixel across an edge is pulled hard toward its neighbors and edges are smoothed; a potential that grows more slowly, such as $|\\Delta|$ or Huber (lecture 16), bounds the force and lets edges survive.',
    check: { question: 'In a homogeneous GMRF with $x^tBx = \\sum_{\\{s,r\\}\\in\\mathcal P}b_{s,r}(x_s-x_r)^2$ and $\\rho(\\Delta) = \\Delta^2/2$, the most probable value of $x_s$ given its neighbors is:', options: ['The weighted mean $\\sum_{r\\in\\partial s}b_{s,r}x_r/\\sum_{r\\in\\partial s}b_{s,r}$', 'The median of the neighbors', 'The largest neighbor', 'Zero, because the field is zero-mean'], answer: 0, explain: 'Force balance $\\sum_r b_{s,r}(\\hat x_s - x_r) = 0$ is linear in $\\hat x_s$ and solves to the weighted average. The median appears instead when $\\rho(\\Delta) = |\\Delta|$ and all weights are equal.' } },

  // ---- Optimization ----------------------------------------------------------
  { id: 'convexity', name: 'Convex functions and unique minima', group: 'Optimization', lectures: [15, 16, 17], figure: 'bowl', dependsOn: ['calculus-1d'], hook: "A convex function is a single valley: wherever you drop a ball it rolls to the same bottom. Add a bowl and the bottom is unique.", bullets: ["Strictly convex: at most one minimiser.", "Proper closed convex + strictly convex quadratic: exactly one minimiser.", "Convex potential + full-rank $A$: unique MAP, ICD converges."], why: "Existence and uniqueness of a proximal map (2024 P3) is this line plus the quadratic.", lesson: 'A strictly convex function has at most one minimizer; a proper closed convex function plus a strictly convex quadratic has exactly one. This is why proximal maps are well defined.' },
  { id: 'case-analysis', name: 'Case analysis with |x|', group: 'Optimization', lectures: [23], figure: 'kink', dependsOn: ['calculus-1d'], hook: "The absolute value hides three functions in one. Solve $x > 0$, $x < 0$ and the kink separately, then keep whichever answer is consistent.", bullets: ["$x>0$: $\\lambda + x - y = 0 \\Rightarrow x = y - \\lambda$, valid if $y > \\lambda$.", "$x<0$: $x = y + \\lambda$, valid if $y < -\\lambda$.", "Else the minimum sits at the kink $x = 0$: shrinkage $S_\\lambda(y)$."], why: "2025 P2 and every $\\ell_1$ proximal map come down to these three cases.", lesson: 'To minimize $\\lambda|x| + \\tfrac12(x-y)^2$, treat $x>0$, $x<0$, $x=0$ separately: the stationary points are $y-\\lambda$ (valid if $y>\\lambda$) and $y+\\lambda$ (valid if $y<-\\lambda$); otherwise the minimum is at the kink $x = 0$. The result is the soft-threshold (shrinkage) function.' },
  { id: 'lagrangian', name: 'Lagrange multipliers', group: 'Optimization', lectures: [21, 22, 24], videos: [{"id": "yuqB-d5MjZA", "title": "Lagrange multipliers, using tangency to solve constrained optimization", "channel": "Khan Academy"}, {"search": "ADMM alternating direction method of multipliers intuition"}], hook: "A multiplier is a price: pay $\\lambda$ per unit of constraint violation, then raise the price until nobody wants to violate it. The augmented term adds a fine that grows with the square.", bullets: ["$L = f(x) + h(v) + \\lambda^t(x - v)$; augmented: add $\\tfrac a2\\|x-v\\|^2$.", "Scaled multiplier $u = \\lambda/a$: the penalty becomes $\\tfrac a2\\|x - v + u\\|^2$.", "ADMM: $x \\leftarrow F(v-u)$, $v \\leftarrow H(x+u)$, $u \\leftarrow u + x - v$."], why: "2022 Q3 asks you to write ADMM from a split problem; the scaled form is the one to memorise.", lesson: 'For $\\min f(x)$ s.t. $x = v$, the Lagrangian is $f(x) + h(v) + \\lambda^t(x-v)$; adding $\\tfrac a2\\|x-v\\|^2$ gives the augmented Lagrangian, and $u = \\lambda/a$ is the scaled multiplier that appears in ADMM as $\\tfrac a2\\|x - v + u\\|^2$.' },
  { id: 'fixed-point', name: 'Contractions, nonexpansive maps, fixed points', group: 'Optimization', lectures: [25], figure: 'contraction', videos: [{"search": "proximal operator fixed point intuition"}], hook: "A contraction shrinks every distance, so iterates have no choice but to pile up on one point. A nonexpansive map may just rotate around it forever; averaging with yourself (Mann) stops the spinning.", bullets: ["Contraction: $\\|H(x)-H(y)\\| \\le c\\|x-y\\|$, $c<1$: unique fixed point, plain iteration converges.", "Nonexpansive: $c \\le 1$; a reflection is the standard counterexample.", "Mann: $x \\leftarrow (1-\\alpha)x + \\alpha H(x)$ converges to a fixed point when one exists."], why: "2025 P4 is exactly this: a swap map, its orbit, and the Mann iteration limit.", lesson: 'A map is a contraction if $\\|H(x)-H(y)\\| \\le c\\|x-y\\|$ with $c<1$, nonexpansive if $c\\le1$. Contractions have a unique fixed point reached by iteration. Nonexpansive maps may oscillate (e.g. a reflection) but the Mann iteration $x \\leftarrow (1-\\alpha)x + \\alpha H(x)$ converges to a fixed point when one exists.' },
]

export const prereqById = Object.fromEntries(prereqs.map((p) => [p.id, p]))
